-- Tabela mock que simula nbs.COMPRA_LANC_CONTAB + CONTA_PAGAR do sistema NBS/SisFin.
-- COD_CONTROLE = LANCAMENTO (sempre iguais nesta base).
-- Centros de custo: 2, 3, 5, 18.

DROP TABLE IF EXISTS public.nbs_mock_lancamentos;

CREATE TABLE public.nbs_mock_lancamentos (
  id               BIGSERIAL     PRIMARY KEY,
  cod_controle     INTEGER       NOT NULL,
  lancamento       INTEGER       NOT NULL,
  cod_empresa      INTEGER       NOT NULL,
  cod_contabil     TEXT          NOT NULL,
  cod_centro_custo INTEGER       NOT NULL,
  valor            NUMERIC(12,2) NOT NULL
);

CREATE INDEX idx_nbs_mock_emp_lanc ON public.nbs_mock_lancamentos(cod_empresa, lancamento);
CREATE INDEX idx_nbs_mock_lancamento ON public.nbs_mock_lancamentos(lancamento);

ALTER TABLE public.nbs_mock_lancamentos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Authenticated read nbs_mock" ON public.nbs_mock_lancamentos
  FOR SELECT TO authenticated USING (true);

